sed -i 's/val downloadManager = ExoDownloadManager.getManager(com.example.OtakuHubApp.instance)/val downloadId = "${download.sourceId}||${download.mangaId}||${download.chapterId}"/g' app/src/main/java/com/example/ui/viewmodels/DownloadViewModel.kt
sed -i 's/val exoDownload = downloadManager.downloadIndex.getDownload("${download.sourceId}||${download.mangaId}||${download.chapterId}")/val mappedProgress = com.example.workers.VideoDownloadService.downloadProgressMap\[downloadId\]?.value\n                    val mappedBytes = com.example.workers.VideoDownloadService.downloadBytesMap\[downloadId\]?.value\n                    val mappedTotalBytes = com.example.workers.VideoDownloadService.downloadTotalBytesMap\[downloadId\]?.value/g' app/src/main/java/com/example/ui/viewmodels/DownloadViewModel.kt
sed -i 's/if (exoDownload != null) {/if (mappedProgress != null) {/g' app/src/main/java/com/example/ui/viewmodels/DownloadViewModel.kt
sed -i 's/progress = exoDownload.percentDownloaded \/ 100f/progress = mappedProgress/g' app/src/main/java/com/example/ui/viewmodels/DownloadViewModel.kt
sed -i 's/bytesDownloaded = exoDownload.bytesDownloaded/bytesDownloaded = mappedBytes ?: 0L/g' app/src/main/java/com/example/ui/viewmodels/DownloadViewModel.kt
sed -i 's/bytesTotal = exoDownload.contentLength/bytesTotal = mappedTotalBytes ?: 0L/g' app/src/main/java/com/example/ui/viewmodels/DownloadViewModel.kt
